import os, glob, struct

def audit_macho(path):
    size = os.path.getsize(path)
    with open(path, 'rb') as f:
        data = f.read()
    if len(data) < 32:
        return (path, False, f'TOO SMALL ({len(data)})')
    magic = struct.unpack('<I', data[:4])[0]
    if magic != 0xfeedfacf:
        return (path, False, f'INVALID MAGIC {hex(magic)}')
    cputype, cpusubtype, filetype, ncmds, sizeofcmds, flags, reserved = struct.unpack('<IIIIIII', data[4:32])

    offset = 32
    max_segment_end = 32 + sizeofcmds
    for i in range(ncmds):
        if offset + 8 > len(data):
            return (path, False, f'TRUNCATED CMDS at {offset}')
        cmd, cmdsize = struct.unpack('<II', data[offset:offset+8])
        cmd_data = data[offset:offset+cmdsize]
        if cmd == 0x19: # LC_SEGMENT_64
            vmaddr, vmsize, fileoff, filesize = struct.unpack('<QQQQ', cmd_data[24:56])
            if fileoff + filesize > max_segment_end:
                max_segment_end = fileoff + filesize
        elif cmd in (0x1d, 0x1e, 0x26, 0x29, 0x2b, 0x2e):
            dataoff, datasize = struct.unpack('<II', cmd_data[8:16])
            if dataoff + datasize > max_segment_end:
                max_segment_end = dataoff + datasize
        offset += cmdsize

    return (path, size == max_segment_end, f'size={size}, expected={max_segment_end}, cmds={ncmds}')

