import os, glob, struct

def parse_bom_store(path):
    size = os.path.getsize(path)
    if size < 512:
        return {'path': path, 'valid': False, 'reason': f'too small ({size})'}
    with open(path, 'rb') as f:
        magic = f.read(8)
        if magic != b'BOMStore':
            return {'path': path, 'valid': False, 'reason': f'invalid magic ({magic})'}
        version, num_blocks, index_offset, index_length = struct.unpack('>IIII', f.read(16))

        # Check index offset bounds
        if index_offset + index_length > size:
            return {'path': path, 'valid': False, 'reason': f'index beyond EOF ({index_offset}+{index_length} > {size})'}

        f.seek(index_offset)
        index_data = f.read(index_length)
        if len(index_data) < 4:
            return {'path': path, 'valid': False, 'reason': 'truncated index'}

        # Check for standard CAR named trees
        f.seek(0)
        full = f.read()
        trees = []
        for marker in [b'CARHEADER', b'KEYFORMAT', b'FACETKEYS', b'RENDITIONS', b'APPEARANCEKEYS']:
            if marker in full:
                trees.append(marker.decode())

        return {
            'path': path,
            'size': size,
            'valid': True,
            'version': version,
            'num_blocks': num_blocks,
            'trees': trees
        }

car_files = glob.glob('extracted/rootfs/**/*.car', recursive=True)
print(f'Found {len(car_files)} .car files')
for c in sorted(car_files):
    res = parse_bom_store(c)
    print(res['path'], '-> Valid:', res.get('valid'), 'Size:', res.get('size'), 'Trees:', res.get('trees'))
